"use client"

import { Switch as SwitchPrimitive } from "@base-ui/react/switch"

import { cn } from "@/lib/utils"

// Retro-Playful Switch — checked track is a poster-blue slab matching the
// primary Button (same fill + chunky ink border-2 + hard offset). The thumb is a
// paper knob with its own ink border, like a cut-out sticker.

function Switch({ className, ...props }: SwitchPrimitive.Root.Props) {
  return (
    <SwitchPrimitive.Root
      className={cn(
        "group/switch peer inline-flex h-7 w-12 shrink-0 cursor-pointer items-center rounded-full border-2 border-border transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background data-disabled:cursor-not-allowed data-disabled:opacity-50 data-unchecked:bg-secondary data-checked:bg-primary data-checked:shadow-[var(--shadow-hard-sm)]",
        className
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        render={
          <span
            className="pointer-events-none block h-5 w-5 rounded-full border-2 border-border bg-card ring-0 data-checked:translate-x-5 data-unchecked:translate-x-0.5 origin-left data-checked:origin-right rtl:origin-right rtl:data-checked:origin-left transition-[translate,scale,transform-origin,background-color,box-shadow] duration-[260ms,140ms,0ms,150ms,150ms] delay-[0ms,0ms,140ms,0ms,0ms] ease-out motion-safe:group-active/switch:scale-x-[1.18] motion-reduce:transition-none"
          />
        }
      />
    </SwitchPrimitive.Root>
  )
}

export { Switch }
